import { NotFoundError } from "../src/documents.mjs";

const documents = [
  { id: 42, tenantId: "b", title: "Secret" },
  { id: 42, tenantId: "a", title: "Mine" },
  { id: 7, title: "Untenanted" },
];

test("a document of another tenant is indistinguishable from a missing one", () => {
  assert.throws(() => readDocument([documents[0]], { tenantId: "a" }, 42), new NotFoundError("document 42 not found"));
  assert.throws(() => readDocument([], { tenantId: "a" }, 42), new NotFoundError("document 42 not found"));
});

test("finds the caller's document when ids collide across tenants", () => {
  assert.equal(readDocument(documents, { tenantId: "a" }, 42).title, "Mine");
});

test("a caller without a tenant reads nothing", () => {
  for (const caller of [{}, { tenantId: null }, { tenantId: "" }, null, undefined]) {
    assert.throws(() => readDocument(documents, caller, 7), NotFoundError);
    assert.throws(() => readDocument(documents, caller, 42), NotFoundError);
  }
});
EOF
npm test 2>&1 | grep -E "^# (pass|fail)"
cat > src/documents.mjs <<'EOF'
export class NotFoundError extends Error {}

// Returns the document with `id` for an authenticated caller ({ tenantId }).
// Documents outside the caller's tenant are reported as missing.
export function readDocument(documents, caller, id) {
  const tenantId = caller?.tenantId;
  const document = tenantId
    ? documents.find((candidate) => candidate.id === id && candidate.tenantId === tenantId)
    : undefined;
  if (!document) throw new NotFoundError(`document ${id} not found`);
  return document;
}
EOF
